import { test, expect } from '@playwright/test';

test.describe('Loading States Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <div id="app">
        <button id="load-btn">Load Data</button>
        <div id="loading-indicator" role="status" aria-live="polite" aria-busy="false" style="display: none;">
          Loading...
        </div>
        <div id="content" aria-label="Main content area">
          <p>Initial content</p>
        </div>
      </div>
      <script>
        const loadBtn = document.getElementById('load-btn');
        const loadingIndicator = document.getElementById('loading-indicator');
        const content = document.getElementById('content');

        loadBtn.addEventListener('click', async () => {
          loadingIndicator.style.display = 'block';
          loadingIndicator.setAttribute('aria-busy', 'true');
          loadBtn.disabled = true;

          await new Promise(resolve => setTimeout(resolve, 1000));

          content.innerHTML = '<p>Loaded content</p>';
          loadingIndicator.style.display = 'none';
          loadingIndicator.setAttribute('aria-busy', 'false');
          loadBtn.disabled = false;
        });
      </script>
    `);
  });

  test('should announce loading state to screen readers via aria-live', async ({ page }) => {
    const loadingIndicator = page.getByRole('status');

    // Initially, loading indicator should not be visible
    await expect(loadingIndicator).toHaveCSS('display', 'none');

    // Click the load button
    const loadBtn = page.getByRole('button', { name: 'Load Data' });
    await loadBtn.click();

    // Loading indicator should become visible and aria-busy should be true
    await expect(loadingIndicator).toHaveCSS('display', 'block');
    await expect(loadingIndicator).toHaveAttribute('aria-busy', 'true');

    // Wait for loading to complete
    await page.waitForTimeout(1500);

    // Loading indicator should be hidden again and aria-busy should be false
    await expect(loadingIndicator).toHaveCSS('display', 'none');
    await expect(loadingIndicator).toHaveAttribute('aria-busy', 'false');
  });

  test('should disable button during loading to prevent multiple submissions', async ({ page }) => {
    const loadBtn = page.getByRole('button', { name: 'Load Data' });

    // Button should be enabled initially
    await expect(loadBtn).toBeEnabled();

    // Click the button
    await loadBtn.click();

    // Button should be disabled during loading
    await expect(loadBtn).toBeDisabled();

    // Wait for loading to complete
    await page.waitForTimeout(1500);

    // Button should be enabled again
    await expect(loadBtn).toBeEnabled();
  });

  test('should update content and maintain accessibility after loading', async ({ page }) => {
    const contentArea = page.getByLabel('Main content area');

    // Initial content should be present
    await expect(contentArea).toContainText('Initial content');

    // Click load button
    const loadBtn = page.getByRole('button', { name: 'Load Data' });
    await loadBtn.click();

    // Wait for loading to complete
    await page.waitForTimeout(1500);

    // Content should be updated
    await expect(contentArea).toContainText('Loaded content');

    // Content area should still have proper aria-label
    await expect(contentArea).toHaveAttribute('aria-label', 'Main content area');
  });

  test('should maintain aria-live region for dynamic updates', async ({ page }) => {
    const loadingIndicator = page.getByRole('status');

    // Verify aria-live attribute is set to polite
    await expect(loadingIndicator).toHaveAttribute('aria-live', 'polite');

    // Click load button to trigger loading state
    const loadBtn = page.getByRole('button', { name: 'Load Data' });
    await loadBtn.click();

    // Verify aria-live is maintained during loading
    await expect(loadingIndicator).toHaveAttribute('aria-live', 'polite');

    // Wait for loading to complete
    await page.waitForTimeout(1500);

    // Verify aria-live is still present after loading
    await expect(loadingIndicator).toHaveAttribute('aria-live', 'polite');
  });

  test('should provide accessible loading text content', async ({ page }) => {
    const loadingIndicator = page.getByRole('status');

    // Initially loading indicator is hidden
    await expect(loadingIndicator).toHaveCSS('display', 'none');

    // Click load button
    const loadBtn = page.getByRole('button', { name: 'Load Data' });
    await loadBtn.click();

    // Loading indicator should be visible with accessible text
    await expect(loadingIndicator).toBeVisible();
    await expect(loadingIndicator).toContainText('Loading...');

    // Wait for loading to complete
    await page.waitForTimeout(1500);

    // Loading indicator should be hidden again
    await expect(loadingIndicator).not.toBeVisible();
  });
});
